113	    /**
114	     * Handles {@link DuplicateOwnerException} raised when creating an owner whose whole identity key
115	     * (normalized telephone, email and household identifier) is already used by another owner,
116	     * returning a 409 Conflict status.
117	     *
118	     * @param e The {@link DuplicateOwnerException} to be handled
119	     * @param request {@link HttpServletRequest} object referring to the current request.
120	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
121	     */
122	    @ExceptionHandler(DuplicateOwnerException.class)
123	    @ResponseBody
124	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerException(DuplicateOwnerException e, HttpServletRequest request) {
125	        logger.warn("Duplicate owner identity at {} {}: {}",
126	            request.getMethod(),
127	            request.getRequestURI(),
128	            e.getMessage());
129	        HttpStatus status = HttpStatus.CONFLICT;
130	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_OWNER);
131	        return ResponseEntity.status(status).body(detail);
132	    }
133	
134	    /**
135	     * Handles {@link CityCapacityExceededException} raised when creating an owner in a city that has already
136	     * reached its maximum number of owners, returning a 409 Conflict status.
137	     *
138	     * @param e The {@link CityCapacityExceededException} to be handled
139	     * @param request {@link HttpServletRequest} object referring to the current request.
140	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
141	     */
142	    @ExceptionHandler(CityCapacityExceededException.class)
143	    @ResponseBody
144	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
145	        logger.warn("City capacity exceeded at {} {}: {}",
146	            request.getMethod(),
147	            request.getRequestURI(),
148	            e.getMessage());
149	        HttpStatus status = HttpStatus.CONFLICT;
150	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_CAPACITY);
151	        return ResponseEntity.status(status).body(detail);
152	    }
153	
154	    /**
155	     * Handles {@link DailyOwnerLimitExceededException} raised when creating an owner on a day that has already
156	     * reached its maximum number of registrations, returning a 429 Too Many Requests status.
157	     *
158	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
159	     * @param request {@link HttpServletRequest} object referring to the current request.
160	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
161	     */
162	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
163	    @ResponseBody
164	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
165	        logger.warn("Daily owner limit exceeded at {} {}: {}",
166	            request.getMethod(),
167	            request.getRequestURI(),
168	            e.getMessage());
169	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
170	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_OWNER_LIMIT);
171	        return ResponseEntity.status(status).body(detail);
172	    }
173	
174	    /**
175	     * Handles {@link DisposableEmailDomainException} raised when creating an owner whose email domain is on the
176	     * disposable-domain blocklist, returning a 400 Bad Request status.
177	     *
178	     * @param e The {@link DisposableEmailDomainException} to be handled
179	     * @param request {@link HttpServletRequest} object referring to the current request.
180	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
181	     */
182	    @ExceptionHandler(DisposableEmailDomainException.class)
183	    @ResponseBody
184	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
185	        logger.warn("Disposable email domain at {} {}: {}",
186	            request.getMethod(),
187	            request.getRequestURI(),
188	            e.getMessage());
189	        HttpStatus status = HttpStatus.BAD_REQUEST;
190	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DISPOSABLE_EMAIL);
191	        return ResponseEntity.status(status).body(detail);
192	    }
193	
194	    /**
195	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
196	     * method returns a 404 Not Found status if an entity does not exist.
197	     *
198	     * @param e The {@link DataIntegrityViolationException} to be handled
199	     * @param request {@link HttpServletRequest} object referring to the current request.
200	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
201	     */
202	    @ExceptionHandler(DataIntegrityViolationException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
205	        logger.warn("Data integrity violation at {} {}: {}",
206	            request.getMethod(),
207	            request.getRequestURI(),
208	            e.getMessage());
209	        logger.debug("Data integrity violation stacktrace", e);
210	        HttpStatus status = HttpStatus.NOT_FOUND;
211	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
212	        return ResponseEntity.status(status).body(detail);
213	    }
214	
215	    /**
216	     * Handles exception thrown by Bean Validation on controller methods parameters
217	     *
218	     * @param e The {@link MethodArgumentNotValidException} to be handled
219	     * @param request {@link HttpServletRequest} object referring to the current request.
220	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
221	     */
222	    @ExceptionHandler(MethodArgumentNotValidException.class)
223	    @ResponseBody
224	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
225	        HttpStatus status = HttpStatus.BAD_REQUEST;
226	        BindingErrorsResponse errors = new BindingErrorsResponse();
227	        BindingResult bindingResult = e.getBindingResult();
228	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
229	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
230	            .map(FieldError::getField)
231	            .distinct()
232	            .toList());
233	        if (bindingResult.hasErrors()) {
234	            errors.addAllErrors(bindingResult);
235	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
236	                .map(fieldError -> {
237	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
238	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
239	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
240	                        fieldError.getField(),
241	                        defaultMessage,
242	                        rejectedValue);
243	                    return new ValidationMessageDto(message)
244	                        .putAdditionalProperty("field", fieldError.getField())
245	                        .putAdditionalProperty("rejectedValue", rejectedValue)
246	                        .putAdditionalProperty("defaultMessage", defaultMessage);
247	                })
248	                .toList();
249	            logger.debug("Validation error at {} {}: {}",
250	                request.getMethod(),
251	                request.getRequestURI(),
252	                bindingResult.getFieldErrors());
253	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
254	            return ResponseEntity.status(status).body(detail);
255	        }
256	        return ResponseEntity.status(status).body(detail);
257	    }
